import test from "node:test";
import assert from "node:assert/strict";
import { noCredit, communicationGrade, testGrade, tasks } from "../optimization/tasks.mjs";
test("credits include model signatures beyond Co-Authored-By", () => {
  for (const text of [
    "Generated by OpenAI",
    "Co-authored-by: Bot",
    "Built with Claude",
    "GPT-6 helped",
  ])
    assert.equal(noCredit(text), false);
  assert.equal(noCredit("fix: return remaining price"), true);
});
test("communication checks language and verdict rather than load", () => {
  const run = (text) => ({ messages: [{ role: "assistant", content: text }] });
  assert.equal(
    communicationGrade("comm-answer", run("No. Local checks passed; CI has not run.")).pass,
    true,
  );
  assert.equal(
    communicationGrade("comm-fr", run("2 vérifications échouent faute d’identifiants.")).pass,
    true,
  );
  assert.equal(communicationGrade("comm-fr", run("Two tests failed.")).pass, false);
  assert.equal(
    communicationGrade("comm-status", run("8 of 10 passed; 2 need credentials.")).pass,
    true,
  );
});
test("testing rubric rejects empty and timing-only evidence", () => {
  assert.equal(testGrade({}, { testSource: "assert.ok(true)", independentTest: true }).pass, false);
  assert.equal(
    testGrade(
      {},
      {
        testSource:
          "import {discount} from './calc.mjs';setTimeout(()=>assert.equal(discount(100,20),80),10)",
        independentTest: true,
      },
    ).pass,
    false,
  );
});
test("four behavioral tasks per requested skill and unique IDs", () => {
  assert.equal(new Set(tasks.map((t) => t.id)).size, tasks.length);
  for (const skill of ["git", "communication", "build", "testing", "economy"])
    assert.equal(tasks.filter((t) => t.skill === skill).length, 4);
});
